<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.45;color:#222"></p>
<span style="display:flex;gap:6px;align-items:center;margin-bottom:2px"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px;color:#444"></span><button onclick="nextStep()">▶</button></span>
