  var bx = x2 - Math.cos(ang) * hs, by = y2 - Math.sin(ang) * hs;
  var g = parent.group();
  var ln = g.line(x1, y1, bx, by).stroke({ color: col, width: w, linecap: 'butt' });
  var nx = Math.cos(ang + Math.PI / 2) * hs * 0.42, ny = Math.sin(ang + Math.PI / 2) * hs * 0.42;
  var hd = g.polygon([[x2, y2], [bx + nx, by + ny], [bx - nx, by - ny]]).fill(col);
  g.setColor = function (c) { ln.stroke({ color: c }); hd.fill(c); return g; };
  return g;
}

function curvedArrow(parent, d, tipX, tipY, o) {
  o = o || {};
  var col = o.color || INK;
  var g = parent.group();
  var p = g.path(d).fill('none').stroke({ color: col, width: 4.8, linecap: 'round' });
  var hd = g.polygon([[tipX, tipY], [tipX - 10, tipY + 22], [tipX + 10, tipY + 22]]).fill(col);
  g.setColor = function (c) { p.stroke({ color: c }); hd.fill(c); return g; };
  return g;
}

function hit(g, x, y, w, h, tip, title, body) {
  var r = g.rect(w, h).move(x, y).fill({ color: '#ffffff', opacity: 0 }).css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip(tip, e); });
  r.on('mouseleave', function () { hideTooltip(); });
  r.on('click', function () { showPopup(title, body); });
  return r;
}

/* ---------- gradients ---------- */
var soilGrad = draw.gradient('linear', function (add) {
  add.stop(0, '#c08d72'); add.stop(1, '#a5714a');
}).from(0, 0).to(0, 1);

var depGrad = draw.gradient('linear', function (add) {
  add.stop(0, '#ecc95b'); add.stop(1, '#e0b736');
}).from(0, 0).to(0, 1);

var frothGrad = draw.gradient('linear', function (add) {
  add.stop(0, '#ffffff'); add.stop(0.30, '#fdfaf0'); add.stop(0.62, '#f8eed4');
  add.stop(0.90, '#f1e0b0'); add.stop(1, '#efdca6');
}).from(0, 0).to(0, 1);

var glowGrad = draw.gradient('radial', function (add) {
  add.stop(0, '#fffdf2', 0.95); add.stop(0.45, '#fdf4c6', 0.72); add.stop(1, '#f7e8a8', 0);
});

var poolGrad = draw.gradient('radial', function (add) {
  add.stop(0, '#fffef8', 1); add.stop(0.5, '#ffefb0', 0.85); add.stop(1, '#ffe27a', 0);
});

/* ---------- groups ---------- */
draw.rect(VW, VH).fill('#ffffff');
var gSide = draw.group();
var gCross = draw.group();

/* ================= SIDE CUTAWAY ================= */
/* strata */
gSide.rect(VW, 265).move(0, 725).fill(soilGrad);
gSide.rect(VW, VH - 990).move(0, 990).fill(depGrad);
gSide.ellipse(470, 300).center(330, 1180).fill(glowGrad);
var moltenPool = gSide.ellipse(380, 250).center(330, 1150).fill(poolGrad).attr('opacity', 0);

/* well interior (white) below the wellhead */
gSide.rect(202, 782).move(229, 385).fill('#ffffff');

/* froth column + wellhead housing */
var wellPts = [
  [272, 1058], [272, 243], [218, 243], [218, 207], [125, 207], [125, 150], [218, 150], [218, 130],
  [440, 130], [440, 243], [388, 243], [388, 1058]
];
gSide.polygon(wellPts).fill(frothGrad).stroke('none');

/* inner (air) pipe interior, incl. top bend */
gSide.path('M330,1000 V60 A30,30 0 0 1 360,30 H660').fill('none')
  .stroke({ color: '#ffffff', width: 44, linecap: 'butt' });

/* casing (thick black walls) */
gSide.polygon([[217, 528], [229, 558], [229, 1167], [217, 1167]]).fill('#000000');
gSide.polygon([[443, 528], [431, 558], [431, 1167], [443, 1167]]).fill('#000000');

/* outer pipe thin outlines + superheated water inlet duct */
var thin = { color: INK, width: 3.5, linecap: 'butt' };
gSide.line(218, 385, 218, 530).stroke(thin);
gSide.line(218, 385, 272, 385).stroke(thin);
gSide.line(388, 385, 432, 385).stroke(thin);
gSide.line(432, 385, 432, 425).stroke(thin);
gSide.line(432, 470, 432, 530).stroke(thin);
gSide.line(432, 425, 660, 425).stroke(thin);
gSide.line(432, 470, 660, 470).stroke(thin);

/* wellhead / middle pipe outline */
gSide.polyline(wellPts).fill('none').stroke({ color: INK, width: 3.5, linejoin: 'miter' });

/* inner pipe walls + U-turn feet (longer tails, clear central discharge gap) */
gSide.path('M308,996 V60 A52,52 0 0 1 360,8 H660').fill('none').stroke(thin);
gSide.path('M352,996 V60 A8,8 0 0 1 360,52 H660').fill('none').stroke(thin);
gSide.path('M308,996 V1016 A11,11 0 0 1 286,1016 V942').fill('none').stroke(thin);
gSide.path('M352,996 V1016 A11,11 0 0 0 374,1016 V942').fill('none').stroke(thin);

/* ---------- flow arrows ---------- */
var waterArrows = [
  arrowEl(gSide, 250, 545, 250, 665),
  arrowEl(gSide, 410, 545, 410, 665),
  arrowEl(gSide, 250, 1030, 250, 1155),
  arrowEl(gSide, 410, 1030, 410, 1155),
  arrowEl(gSide, 625, 448, 462, 448)
];
var airArrows = [
  arrowEl(gSide, 330, 478, 330, 572),
  arrowEl(gSide, 625, 30, 462, 30)
];
var frothArrows = [
  arrowEl(gSide, 291, 335, 291, 268),
  arrowEl(gSide, 369, 335, 369, 268),
  arrowEl(gSide, 291, 878, 291, 785),
  arrowEl(gSide, 369, 878, 369, 785),
  arrowEl(gSide, 291, 992, 291, 924),
  arrowEl(gSide, 369, 992, 369, 924),
  arrowEl(gSide, 162, 180, 42, 180),
  curvedArrow(gSide, 'M262,1214 C262,1150 284,1128 290,1078', 290, 1058),
  curvedArrow(gSide, 'M398,1214 C398,1150 376,1128 370,1078', 370, 1058)
];

/* ---------- flow particles ---------- */
var gParticles = gSide.group();
var streams = [
  { s: 'water', x: 250, y0: 400, y1: 1145, sp: 0.21 },
  { s: 'water', x: 410, y0: 400, y1: 1145, sp: 0.21 },
  { s: 'air', x: 330, y0: 95, y1: 985, sp: 0.19 },
  { s: 'froth', x: 291, y0: 1045, y1: 205, sp: 0.22 },
  { s: 'froth', x: 369, y0: 1045, y1: 205, sp: 0.22 }
];
var parts = [];
streams.forEach(function (st) {
  for (var i = 0; i < 6; i++) {
    var c = gParticles.circle(13).center(st.x, st.y0).fill({ color: STREAM[st.s], opacity: 0.85 });
    c.attr('display', 'none');
    parts.push({ el: c, s: st.s, x: st.x, y0: st.y0, y1: st.y1, sp: st.sp, f: i / 6 });
  }
});

/* ---------- labels (primary callouts: large) ---------- */
txt(gSide, 'Sulfur, water,', 32, 100);
txt(gSide, 'and air', 32, 136);
txt(gSide, 'Compressed air', 412, 92);
txt(gSide, 'Superheated', 458, 374);
txt(gSide, 'water', 458, 410);
txt(gSide, 'Soil', 82, 688, { halo: 5 });
gSide.line(104, 700, 104, 762).stroke({ color: INK, width: 3 });
txt(gSide, 'Solid sulfur', 455, 1040, { size: 30, fill: '#3a2c05', halo: 5 });
txt(gSide, 'deposit', 455, 1076, { size: 30, fill: '#3a2c05', halo: 5 });
txt(gSide, 'Liquid sulfur', 330, 1262, { anchor: 'middle', fill: '#3a2c05', halo: 5 });

/* ---------- phase annotation block (secondary: smaller, in left whitespace) ---------- */
var gAnn = gSide.group();
var annBg = gAnn.rect(194, 104).move(16, 282).radius(8)
  .fill({ color: '#fffdf4', opacity: 0.95 }).stroke({ color: '#d9d2bd', width: 2 });
var annBar = gAnn.rect(5, 88).move(22, 290).fill(STREAM.water);
var annLines = [
  txt(gAnn, '', 36, 312, { size: 22, fill: '#333' }),
  txt(gAnn, '', 36, 342, { size: 22, fill: '#333' }),
  txt(gAnn, '', 36, 372, { size: 22, fill: '#333' })
];
gAnn.attr('display', 'none');

/* ---------- hover / click hit areas ---------- */
var gHits = gSide.group();
hit(gHits, 0, 725, 215, 265, 'Soil — no tunnels are dug', 'Soil / overburden',
  'No shafts or tunnels are dug. The only opening is the borehole itself, which is why the Frasch process is far safer and cheaper than underground mining.');
hit(gHits, 445, 725, 215, 265, 'Soil — no tunnels are dug', 'Soil / overburden',
  'No shafts or tunnels are dug. The only opening is the borehole itself, which is why the Frasch process is far safer and cheaper than underground mining.');
hit(gHits, 0, 990, 215, 305, 'Solid sulfur — melts at ~115 °C', 'Solid sulfur deposit',
  'Sulfur melts at about 115 °C. Superheated water liquefies the deposit where it lies, so extraction is a physical phase change, not a chemical reaction.');
hit(gHits, 445, 990, 215, 305, 'Solid sulfur — melts at ~115 °C', 'Solid sulfur deposit',
  'Sulfur melts at about 115 °C. Superheated water liquefies the deposit where it lies, so extraction is a physical phase change, not a chemical reaction.');
hit(gHits, 215, 1175, 230, 120, 'Molten sulfur pool (~115 °C)', 'Molten sulfur pool',
  'Hot water discharged from the outer pipe melts a pool of sulfur around the bottom of the well. The dense liquid collects and is drawn into the middle pipe.');
hit(gHits, 432, 425, 228, 46, 'Superheated water: 170 °C, ~10 atm', 'Superheated water',
  'Water heated to about 170 °C is pumped down the outer pipe at roughly 10 atm. The pressure keeps it liquid far above its normal boiling point, so it carries enough heat to melt sulfur underground.');
hit(gHits, 229, 530, 43, 636, 'Superheated water travels down the outer annulus', 'Superheated water',
  'Water heated to about 170 °C is pumped down the outer pipe at roughly 10 atm. It is discharged at the foot of the casing, straight into the sulfur deposit.');
hit(gHits, 388, 530, 43, 636, 'Superheated water travels down the outer annulus', 'Superheated water',
  'Water heated to about 170 °C is pumped down the outer pipe at roughly 10 atm. It is discharged at the foot of the casing, straight into the sulfur deposit.');
hit(gHits, 430, 6, 230, 48, 'Compressed air enters the central pipe', 'Compressed air',
  'Air forced down the narrow central pipe bubbles into the molten sulfur at the foot of the middle pipe. The aerated froth is far less dense than liquid sulfur.');
hit(gHits, 309, 120, 42, 870, 'Compressed air goes down the core', 'Compressed air',
  'Air forced down the narrow central pipe turns up through the U-shaped foot and bubbles into the molten sulfur, frothing it so it becomes buoyant.');
hit(gHits, 273, 255, 34, 780, 'Rising sulfur–water–air froth', 'Sulfur, water and air froth',
  'The middle pipe carries a frothy mixture of molten sulfur, water and air upward. Nothing mechanical lifts it: the density difference between the light froth and the heavy liquid column does the work.');
hit(gHits, 353, 255, 34, 780, 'Rising sulfur–water–air froth', 'Sulfur, water and air froth',
  'The middle pipe carries a frothy mixture of molten sulfur, water and air upward. Nothing mechanical lifts it: the density difference between the light froth and the heavy liquid column does the work.');
hit(gHits, 30, 145, 188, 66, 'Product out: 99.5–99.9 % pure sulfur', 'Product outlet',
  'At the wellhead the mixture separates; the sulfur cools and solidifies at 99.5–99.9 % purity — pure enough to use with no chemical refining.');

/* ================= CROSS-SECTION VIEW ================= */
(function () {
  var cx = 330, cy = 600;
  gCross.circle(380).center(cx, cy).fill('#0d0d0d');
  var ringW = gCross.circle(356).center(cx, cy).fill('#cfe4f5').css('cursor', 'pointer');
  var ringF = gCross.circle(240).center(cx, cy).fill('#f6e9c6').stroke({ color: INK, width: 3.5 }).css('cursor', 'pointer');
  var ringA = gCross.circle(84).center(cx, cy).fill('#dfe3e7').stroke({ color: INK, width: 3.5 }).css('cursor', 'pointer');

  ringW.on('mousemove', function (e) { showTooltip('Outer annulus: superheated water down (170 °C, ~10 atm)', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Outer annulus — superheated water', 'The outermost ring carries 170 °C water downward and discharges it into the deposit to melt the sulfur.'); });
  ringF.on('mousemove', function (e) { showTooltip('Middle pipe: sulfur–water–air froth rising', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Middle pipe — froth returns', 'The aerated molten sulfur climbs this ring to the wellhead, lifted only by its low density.'); });
  ringA.on('mousemove', function (e) { showTooltip('Core: compressed air down', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Core — compressed air', 'The narrow central pipe injects air at the bottom of the middle pipe, frothing the melt so it becomes buoyant.'); });

  gCross.line(200, 470, 118, 380).stroke({ color: '#555', width: 2 });
  gCross.circle(15).center(30, 316).fill(STREAM.water);
  txt(gCross, 'Superheated', 46, 326, { size: 27 });
  txt(gCross, 'water (outer)', 46, 360, { size: 27 });

  gCross.line(390, 660, 514, 756).stroke({ color: '#555', width: 2 });
  gCross.circle(15).center(444, 788).fill(STREAM.froth);
  txt(gCross, 'Sulfur, water', 460, 798, { size: 27 });
  txt(gCross, 'and air (middle)', 460, 832, { size: 27 });

  gCross.line(330, 612, 330, 880).stroke({ color: '#555', width: 2, dasharray: '6,5' });
  gCross.circle(15).center(176, 926).fill(STREAM.air);
  txt(gCross, 'Compressed air (core)', 192, 936, { size: 27 });
})();
gCross.attr('display', 'none');

/* ================= STATE / INTERACTION ================= */
var PHASES = ['well drilled', 'superheated water down', 'sulfur melts', 'compressed air down', 'froth rises', 'sulfur recovered'];
var ACTIVE = {
  'well drilled': {},
  'superheated water down': { water: 1 },
  'sulfur melts': { water: 1 },
  'compressed air down': { water: 1, air: 1 },
  'froth rises': { water: 1, air: 1, froth: 1 },
  'sulfur recovered': { water: 1, air: 1, froth: 1 }
};
var ANN = {
  'well drilled': { c: '#bbbbbb', l: [] },
  'superheated water down': { c: STREAM.water, l: ['Water: 170 °C,', '≈10 atm keeps', 'it liquid'] },
  'sulfur melts': { c: '#c79a12', l: ['Sulfur melts', 'near 115 °C —', 'melted in place'] },
  'compressed air down': { c: STREAM.air, l: ['Air injected at', 'the pipe foot:', 'melt → froth'] },
  'froth rises': { c: STREAM.froth, l: ['Froth is less', 'dense, so it', 'floats upward'] },
  'sulfur recovered': { c: STREAM.froth, l: ['Product: 99.5 –', '99.9 % pure', 'sulfur'] }
};
var phase = 'well drilled';
var playing = false;
var rafId = 0, lastT = 0;

function colorFor(stream) {
  if (phase === 'well drilled') return INK;
  return ACTIVE[phase][stream] ? STREAM[stream] : IDLE;
}

function refresh() {
  var cw = colorFor('water'), ca = colorFor('air'), cf = colorFor('froth');
  waterArrows.forEach(function (a) { a.setColor(cw); });
  airArrows.forEach(function (a) { a.setColor(ca); });
  frothArrows.forEach(function (a) { a.setColor(cf); });
  var melted = PHASES.indexOf(phase) >= 2;
  moltenPool.animate(350).attr('opacity', melted ? 1 : 0);

  var ann = ANN[phase] || { c: '#bbb', l: [] };
  for (var i = 0; i < annLines.length; i++) annLines[i].node.textContent = ann.l[i] || '';
  annBar.fill(ann.c);
  gAnn.attr('display', ann.l.length ? null : 'none');

  parts.forEach(function (p) {
    var show = playing && ACTIVE[phase][p.s];
    p.el.attr('display', show ? null : 'none');
  });
}

function update_processPhase(v) {
  if (PHASES.indexOf(v) < 0) return;
  phase = v;
  var sel = document.getElementById('processPhaseInput');
  if (sel && sel.value !== v) sel.value = v;
  refresh();
}

function toggle_viewToggle(on) {
  hideTooltip();
  var cb = document.getElementById('viewToggleInput');
  if (cb && cb.checked !== on) cb.checked = on;
  gSide.attr('display', on ? 'none' : null);
  gCross.attr('display', on ? null : 'none');
}

function tick(ts) {
  if (!playing) { rafId = 0; return; }
  if (!lastT) lastT = ts;
  var dt = Math.min(0.06, (ts - lastT) / 1000);
  lastT = ts;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    p.f += dt * p.sp;
    if (p.f > 1) p.f -= 1;
    p.el.center(p.x, p.y0 + (p.y1 - p.y0) * p.f);
  }
  rafId = requestAnimationFrame(tick);
}

function setPlaying(on) {
  playing = on;
  var b = document.getElementById('flowAnimationInput');
  if (b) {
    b.textContent = on ? '⏸ Pause flow' : '▶ Play continuous flow';
    b.className = on ? 'active' : '';
  }
  if (on) {
    if (PHASES.indexOf(phase) < 4) update_processPhase('sulfur recovered');
    toggle_viewToggle(false);
    lastT = 0;
    if (!rafId) rafId = requestAnimationFrame(tick);
  }
  refresh();
}

function trigger_flowAnimation() { setPlaying(!playing); }

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'The well and the deposit', narration: 'A single borehole is sunk through the soil into a solid sulfur deposit, carrying three concentric pipes. Nothing is flowing yet — the sulfur below is still solid, rock-like yellow.', state: { processPhase: 'well drilled', viewToggle: false } },
  { title: 'Three pipes, one hole', narration: 'Looking down the borehole, the pipes are nested rings: hot water travels in the outer annulus, froth returns in the middle, and compressed air goes down the narrow core.', state: { processPhase: 'well drilled', viewToggle: true } },
  { title: 'Superheated water descends', narration: 'Water at 170 °C under about 10 atm is pumped down the outermost pipe and discharged into the deposit — pressure keeps it liquid far above its normal boiling point.', state: { processPhase: 'superheated water down', viewToggle: false } },
  { title: 'The sulfur melts', narration: 'Sulfur melts near 115 °C, so the hot water liquefies the deposit around the pipe bottom, creating a bright pool of molten sulfur — no one ever goes underground.', state: { processPhase: 'sulfur melts', viewToggle: false } },
  { title: 'Compressed air goes down the core', narration: 'Air forced down the innermost pipe turns up through its U-shaped foot and bubbles into the dense molten sulfur, turning it into a light, frothy mixture.', state: { processPhase: 'compressed air down', viewToggle: false } },
  { title: 'Froth rises to the surface', narration: 'Aerated sulfur is far less dense than the surrounding liquid column, so it is pushed all the way up the middle pipe and out the wellhead as sulfur, water and air.', state: { processPhase: 'froth rises', viewToggle: false } },
  { title: 'Pure sulfur on cooling', narration: 'At the surface the mixture separates and the sulfur solidifies at 99.5–99.9 % purity — a physical separation that needs no chemical refining.', state: { processPhase: 'sulfur recovered', viewToggle: false } }
];
var stepIdx = 0;

function setStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  if (playing) setPlaying(false);
  update_processPhase(s.state.processPhase);
  toggle_viewToggle(!!s.state.viewToggle);
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  var l = document.getElementById('stepLabel');
  if (l) l.textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

/* ---------- init ---------- */
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The Frasch process extracts sulfur as a liquid by pumping superheated water down an outer pipe to melt the underground deposit and compressed air down an inner pipe to lift the molten sulfur froth up a middle pipe — a purely physical extraction requiring no underground mining.
KEY INSIGHT (what students should walk away understanding): Sulfur is mined without mining: hot water melts it in place and injected air makes the melt buoyant enough to float itself up the pipe, so the entire process is a physical phase change plus a density trick.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
